import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useAsyncTexture } from '../../../hooks/useAsyncTexture';

const WormholeGold = ({ position, rotation = [0, 0, 0], length = 2000, radius = 200, logoPath = "/legal_eagle_logo.png", visible }) => {
  const groupRef = useRef();
  const shaderRef = useRef();
  
  // Load the logo texture
  const logoTexture = useAsyncTexture(logoPath);

  const uniforms = useMemo(() => ({
    uTime: { value: 0 },
    uColor: { value: new THREE.Color("#ffaa00") } // Rich golden/amber color
  }), []);

  useFrame((state) => {
    if (shaderRef.current) {
      shaderRef.current.uniforms.uTime.value = state.clock.elapsedTime;
    }
    if (groupRef.current && visible) {
      // Gentle counter-rotation for parallax effect
      groupRef.current.rotation.z = -state.clock.elapsedTime * 0.15;
    }
  });

  // Generate glowing neon gold rings along the Z-axis of the wormhole
  const rings = useMemo(() => {
    const list = [];
    const count = 12; // 12 rings along 2000 units is a nice density
    for (let i = 0; i < count; i++) {
      list.push({
        z: -(i / (count - 1)) * length
      });
    }
    return list;
  }, [length]);

  return (
    <group position={position} rotation={rotation} visible={visible}>
      <group ref={groupRef}>
        {/* Main Golden cyber tunnel cylinder - rotated once here to lie along Z-axis */}
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, 0, -length / 2]}>
          <cylinderGeometry args={[radius, radius, length, 64, 30, true]} />
          <shaderMaterial
            ref={shaderRef}
            transparent
            side={THREE.BackSide}
            blending={THREE.AdditiveBlending}
            depthWrite={false}
            uniforms={uniforms}
            vertexShader={`
              varying vec2 vUv;
              varying vec3 vPosition;
              void main() {
                vUv = uv;
                vPosition = position;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
              }
            `}
            fragmentShader={`
              uniform float uTime;
              uniform vec3 uColor;
              varying vec2 vUv;
              varying vec3 vPosition;
              
              void main() {
                // High frequency golden spiral lines
                float gridU = abs(sin(vUv.x * 60.0 + uTime * 2.0));
                float gridV = abs(sin(vUv.y * 120.0 - uTime * 15.0));
                float grid = smoothstep(0.96, 1.0, gridU) + smoothstep(0.98, 1.0, gridV);
                
                // Fast-moving golden energy pulses zipping down the tunnel
                float pulses = sin((vUv.x * 12.0) + sin(vUv.y * 3.0)) * sin((vUv.y * 50.0) - (uTime * 35.0));
                pulses = smoothstep(0.85, 1.0, pulses) * 2.5;

                // Base ambient glow inside the tunnel
                float glow = 0.15 + 0.1 * sin(uTime * 2.0 + vUv.y * 5.0);

                // Mix grid and pulses
                float intensity = (grid * 0.4 + pulses * 0.6) + glow;

                // Edge fade at the start and end of the wormhole
                float edgeFade = smoothstep(0.0, 0.1, vUv.y) * smoothstep(1.0, 0.85, vUv.y);

                gl_FragColor = vec4(uColor, intensity * edgeFade);
              }
            `}
          />
        </mesh>

        {/* Golden laser rings perpendicular to Z-axis (no rotation needed since ringGeometry faces Z) */}
        {rings.map((ring, idx) => (
          <group key={idx} position={[0, 0, ring.z]}>
            <mesh>
              <ringGeometry args={[radius * 0.97, radius, 64]} />
              <meshBasicMaterial color="#ffaa00" side={THREE.DoubleSide} transparent opacity={0.6} />
            </mesh>
            <mesh scale={[1.05, 1.05, 1.05]}>
              <ringGeometry args={[radius * 0.95, radius, 64]} />
              <meshBasicMaterial color="#ffd700" side={THREE.DoubleSide} transparent opacity={0.2} blending={THREE.AdditiveBlending} />
            </mesh>
          </group>
        ))}
      </group>

      {/* Floating 2D Logo at the end exit facing Z (no rotation needed) */}
      <mesh position={[0, 0, -length]}>
        <planeGeometry args={[180, 180]} />
        <meshBasicMaterial map={logoTexture} transparent={true} depthWrite={false} />
      </mesh>
    </group>
  );
};

export default WormholeGold;
