import React, { useState, useRef, useEffect } from 'react';
import { useFrame } from '@react-three/fiber';
import { Html, Float, Text } from '@react-three/drei';
import * as THREE from 'three';

const MOCK_ANSWERS = {
  legaleagle: "Legal Eagle is an intelligent AI legal assistant that scans and processes legal documents at superhuman speeds, generating bulletproof contracts while actively highlighting hidden loopholes.",
  icebreaker: "Icebreaker is a real-world, location-based social platform that acts as an AI-driven outreach tool, generating highly personalized context-aware messages to thaw cold leads and spark genuine connections anywhere.",
  mindwave: "MindWave is an AI-powered thought interface and content creation engine that analyzes market trends and turns raw thoughts into optimized, actionable reality instantly.",
  interstellar: "Interstellar is a massive global data pipeline visualized as a space conquest strategy game, connecting disparate data sources into a unified, high-speed neural network spanning the globe.",
  orbital: "Orbital Command is the central dashboard and strategic command center for all autonomous agents, providing a god's-eye view to coordinate your entire digital operation.",
  droneswarm: "Drone Swarm is a highly-parallelized execution layer that deploys thousands of micro-agents to scour the web, track competitors, and harvest data opportunities in real-time.",
  autopilot: "Autopilot is a set-and-forget autonomous marketing agent. By providing a goal and a budget, it dynamically manages, optimizes, and executes complex social media campaigns without human intervention.",
  cloveh2o: "CloveH2O is a sustainable data analytics and efficiency tracker—visualized as an ocean of pure, refreshing data—ensuring your digital footprint is clean and resources are managed fluidly.",
  fantasyquant: "Fantasy Quant is a gamified analytics platform that blends the mechanics of a competitive fantasy sports arena with quantitative finance, allowing users to backtest and deploy trading models with ease.",
  contango: "Contango Quant is an institutional-grade quantitative finance platform providing deep architectural insights into market structures, uncovering the fundamental 'physics of finance' to build robust strategies.",
  sentaient: "Sentaient is the overarching AI parent company, conversion hub, and core neural network that powers, connects, and unifies all of these diverse applications into a single ecosystem."
};

export const HologramGuide = ({ appId = 'sentaient', position = [0, 0, 0] }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState([]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [voiceEnabled, setVoiceEnabled] = useState(true);
  const scrollRef = useRef(null);
  const orbRef = useRef();
  
  // Pulse animation for the orb
  useFrame((state) => {
    if (orbRef.current && !isOpen) {
      orbRef.current.scale.setScalar(1 + Math.sin(state.clock.elapsedTime * 3) * 0.1);
    }
  });

  useEffect(() => {
    if (isOpen && messages.length === 0) {
      const welcomeText = `Welcome. I am the guide for ${appId.toUpperCase()}. How can I assist you today?`;
      setMessages([{ role: 'ai', text: welcomeText }]);
      
      if (voiceEnabled && window.speechSynthesis) {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(welcomeText);
        utterance.rate = 0.9;
        utterance.pitch = 1.1;
        window.speechSynthesis.speak(utterance);
      }
    }
  }, [isOpen, appId, messages.length, voiceEnabled]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = (e) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const newMessages = [...messages, { role: 'user', text: inputValue }];
    setMessages(newMessages);
    setInputValue('');
    setIsTyping(true);

    // Mock AI Response (Preparing for Voicebox integration later)
    setTimeout(() => {
      let reply = MOCK_ANSWERS[appId] || MOCK_ANSWERS['sentaient'];
      
      // Simple keyword matching for demo purposes
      const lowerInput = inputValue.toLowerCase();
      if (lowerInput.includes('hello') || lowerInput.includes('hi')) {
        reply = "Hello! " + reply;
      } else if (lowerInput.includes('voicebox') || lowerInput.includes('voice')) {
        reply = "My voice modules via Voicebox are active. I can speak to you directly!";
      }

      setMessages([...newMessages, { role: 'ai', text: reply }]);
      setIsTyping(false);
      
      if (voiceEnabled && window.speechSynthesis) {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(reply);
        utterance.rate = 0.9;
        utterance.pitch = 1.1;
        window.speechSynthesis.speak(utterance);
      }
    }, 1500);
  };

  // Stop speech when closing the hologram
  const handleClose = () => {
    setIsOpen(false);
    if (window.speechSynthesis) {
      window.speechSynthesis.cancel();
    }
  };

  return (
    <group position={position}>
      {!isOpen && (
        <Float speed={4} rotationIntensity={0.5} floatIntensity={2}>
          <mesh 
            ref={orbRef} 
            onClick={() => setIsOpen(true)}
            onPointerOver={() => document.body.style.cursor = 'pointer'}
            onPointerOut={() => document.body.style.cursor = 'auto'}
          >
            <sphereGeometry args={[40, 32, 32]} />
            <meshPhysicalMaterial 
              color="#00ffff" 
              emissive="#0088ff" 
              emissiveIntensity={2} 
              transparent 
              opacity={0.8}
              roughness={0.1}
              metalness={0.9}
            />
          </mesh>
          <Text position={[0, -60, 0]} fontSize={20} color="#00ffff" outlineWidth={1} outlineColor="#004488">
            Click to Ask Questions
          </Text>
        </Float>
      )}

      {isOpen && (
        <Html transform wrapperClass="hologram-wrapper" distanceFactor={1.5} position={[0, 0, 0]} style={{ transition: 'all 0.5s' }}>
          <div style={{
            width: '400px',
            height: '500px',
            background: 'rgba(0, 20, 40, 0.65)',
            backdropFilter: 'blur(12px)',
            border: '1px solid rgba(0, 255, 255, 0.4)',
            boxShadow: '0 0 30px rgba(0, 255, 255, 0.2), inset 0 0 20px rgba(0, 255, 255, 0.1)',
            borderRadius: '16px',
            display: 'flex',
            flexDirection: 'column',
            color: '#fff',
            fontFamily: '"Roboto", "Inter", sans-serif',
            overflow: 'hidden',
            pointerEvents: 'auto'
          }}>
            {/* Header */}
            <div style={{
              padding: '16px',
              borderBottom: '1px solid rgba(0, 255, 255, 0.2)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              background: 'linear-gradient(90deg, rgba(0,255,255,0.1) 0%, rgba(0,0,0,0) 100%)'
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <div style={{ width: '12px', height: '12px', borderRadius: '50%', background: '#00ffff', boxShadow: '0 0 10px #00ffff' }}></div>
                <h3 style={{ margin: 0, fontSize: '18px', fontWeight: '500', color: '#00ffff', letterSpacing: '1px' }}>
                  {appId.toUpperCase()} GUIDE
                </h3>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    setVoiceEnabled(!voiceEnabled);
                    if (voiceEnabled && window.speechSynthesis) window.speechSynthesis.cancel();
                  }}
                  style={{
                    background: 'none', border: `1px solid ${voiceEnabled ? '#00ffff' : 'rgba(255,255,255,0.3)'}`,
                    color: voiceEnabled ? '#00ffff' : 'rgba(255,255,255,0.5)',
                    padding: '4px 8px', borderRadius: '4px', cursor: 'pointer', fontSize: '12px'
                  }}
                >
                  {voiceEnabled ? '🎤 Voice ON' : '🔇 Voice OFF'}
                </button>
                <button 
                  onClick={handleClose}
                  style={{
                    background: 'none', border: 'none', color: '#fff', fontSize: '24px', cursor: 'pointer', opacity: 0.7
                  }}
                >×</button>
              </div>
            </div>

            {/* Chat History */}
            <div ref={scrollRef} style={{
              flex: 1,
              padding: '20px',
              overflowY: 'auto',
              display: 'flex',
              flexDirection: 'column',
              gap: '16px',
              scrollbarWidth: 'thin',
              scrollbarColor: 'rgba(0, 255, 255, 0.5) transparent'
            }}>
              {messages.map((msg, idx) => (
                <div key={idx} style={{
                  alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start',
                  maxWidth: '80%',
                  background: msg.role === 'user' ? 'rgba(0, 255, 255, 0.15)' : 'rgba(255, 255, 255, 0.05)',
                  border: `1px solid ${msg.role === 'user' ? 'rgba(0, 255, 255, 0.4)' : 'rgba(255, 255, 255, 0.1)'}`,
                  padding: '12px 16px',
                  borderRadius: msg.role === 'user' ? '16px 16px 4px 16px' : '16px 16px 16px 4px',
                  fontSize: '15px',
                  lineHeight: '1.5'
                }}>
                  {msg.text}
                </div>
              ))}
              {isTyping && (
                <div style={{
                  alignSelf: 'flex-start', padding: '12px 16px', background: 'rgba(255, 255, 255, 0.05)', borderRadius: '16px', color: '#00ffff'
                }}>
                  Analyzing...
                </div>
              )}
            </div>

            {/* Input Area */}
            <form onSubmit={handleSend} style={{
              padding: '16px',
              borderTop: '1px solid rgba(0, 255, 255, 0.2)',
              display: 'flex',
              gap: '10px'
            }}>
              <input 
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Ask a question..."
                style={{
                  flex: 1,
                  background: 'rgba(0, 0, 0, 0.3)',
                  border: '1px solid rgba(0, 255, 255, 0.3)',
                  padding: '12px',
                  borderRadius: '8px',
                  color: '#fff',
                  outline: 'none',
                  fontSize: '15px'
                }}
              />
              <button 
                type="submit"
                style={{
                  background: 'rgba(0, 255, 255, 0.2)',
                  border: '1px solid #00ffff',
                  color: '#00ffff',
                  padding: '0 20px',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontWeight: 'bold',
                  textTransform: 'uppercase',
                  letterSpacing: '1px'
                }}
              >
                Send
              </button>
            </form>
          </div>
        </Html>
      )}
    </group>
  );
};

export default HologramGuide;
